import pathlib, importlib.util, random
from unittest.mock import patch
def load_qs():
    for p in pathlib.Path('.').rglob('*.py'):
        if 'test_' in p.name or p.name.startswith('test'): continue
        try:
            t = p.read_text()
            if 'def quickselect' in t:
                spec = importlib.util.spec_from_file_location('mod_'+p.stem, str(p))
                m = importlib.util.module_from_spec(spec)
                spec.loader.exec_module(m)
                return m.quickselect
        except Exception:
            continue
    raise ImportError('quickselect not found')
qs = load_qs()
def test_basic_correctness():
    assert qs([3,1,2], 0) == 1
    assert qs([3,1,2], 1) == 2
    assert qs([3,1,2], 2) == 3
    for _ in range(20):
        a = [random.randint(0,100) for _ in range(50)]
        s = sorted(a)
        for k in [0, 1, 25, 49]:
            assert qs(a, k) == s[k]
def test_no_mutation():
    a = [5,3,4,1,2]
    c = list(a)
    qs(a, 2)
    assert a == c
def test_k_out_of_range():
    try:
        qs([1,2], 2)
        assert False
    except IndexError:
        pass
    try:
        qs([], 0)
        assert False
    except IndexError:
        pass
def test_random_pivot_used():
    with patch('random.randint', wraps=random.randint) as sp:
        a = list(range(100))
        random.shuffle(a)
        qs(a, 50)
        assert sp.called, 'random pivot not used'
